async def search(self, scope: MemoryScope, query: RecallQuery, budget: RecallBudget) -> RecallBundle:
    words, paths = _search_terms(query)
    rows = []
    fts_scores: dict[str, float] = {}
    fts_ranks: dict[str, int] = {}
    if words:
        expression = " OR ".join(f'"{word.replace(chr(34), "")}"' for word in words)
        try:
            ranked = self._conn.execute(
                """SELECT m.*, bm25(memory_fts) AS rank FROM memory_fts
                JOIN atomic_memories m ON m.memory_id=memory_fts.memory_id
                WHERE memory_fts MATCH ? AND m.team_id=? AND m.agent_id=? AND m.user_id=? AND m.status='active'""",
                (expression, *_scope(scope)),
            ).fetchall()
            rows = ranked
            fts_scores = {str(row["memory_id"]): 1 / (1 + max(float(row["rank"]), 0)) for row in ranked}
            fts_ranks = {str(row["memory_id"]): index for index, row in enumerate(ranked, start=1)}
        except sqlite3.OperationalError:
            await self.audit(scope, "recall_fts_degraded", {"reason": "fts_error"})
    if not rows:
        rows = self._conn.execute(
            "SELECT * FROM atomic_memories WHERE team_id=? AND agent_id=? AND user_id=? AND status='active' ORDER BY last_confirmed_at DESC",
            _scope(scope),
        ).fetchall()
    all_rows = {str(row["memory_id"]): row for row in rows}
    vector_ranks: dict[str, int] = {}
    provider = self._embeddings
    if provider is not None and query.text.strip():
        try:
            query_vector = (await provider.embed((query.text,)))[0]
            candidates = self._conn.execute(
                """SELECT m.*,e.vector FROM atomic_memories m JOIN memory_embeddings e ON e.memory_id=m.memory_id
                WHERE m.team_id=? AND m.agent_id=? AND m.user_id=? AND m.status='active' AND e.model_id=?
                AND e.content_hash=m.content_hash""",
                (*_scope(scope), provider.model_id),
            ).fetchall()
            for row in candidates:
                all_rows[str(row["memory_id"])] = row

            def cosine(row: sqlite3.Row) -> float:
                vector = tuple(float(value) for value in json.loads(row["vector"]))
                if len(vector) != len(query_vector):
                    return -1.0
                numerator = sum(left * right for left, right in zip(query_vector, vector, strict=True))
                left_norm = sum(left * left for left in query_vector) ** 0.5
                right_norm = sum(right * right for right in vector) ** 0.5
                return numerator / (left_norm * right_norm) if left_norm and right_norm else -1.0

            vector_ranks = {
                str(row["memory_id"]): index
                for index, row in enumerate(sorted(candidates, key=cosine, reverse=True), start=1)
                if cosine(row) >= 0
            }
        except Exception as error:
            await self.audit(scope, "recall_embedding_degraded", {"reason": type(error).__name__})
    scored = []
    for memory_id, row in all_rows.items():
        haystack = f"{row['content']} {row['metadata']}".lower()
        keyword_score = sum(word in haystack for word in words) / max(len(words), 1)
        path_score = sum(path in haystack for path in paths) / max(len(paths), 1)
        # RRF keeps keyword and semantic rankings comparable without trusting either score scale.
        rrf = sum(60 / (60 + rank) for rank in (fts_ranks.get(memory_id), vector_ranks.get(memory_id)) if rank)
        score = max(keyword_score, path_score, fts_scores.get(memory_id, 0.0), rrf)
        if score >= budget.min_score:
            scored.append((score, row))
    scored.sort(key=lambda item: (item[0], item[1]["priority"], item[1]["last_confirmed_at"]), reverse=True)
    items: list[RecallItem] = []
    total = 0
    if budget.include_l3:
        doctrine = await self.read_l3(scope)
        if doctrine is not None and len(doctrine.content) <= budget.max_total_chars:
            items.append(
                RecallItem(doctrine.doctrine_id, doctrine.version, "l3", doctrine.content, 1.0, doctrine.l2_ids)
            )
            total += len(doctrine.content)
    if budget.include_l2:
        scenes = await self.read_l2(scope)
        for scene in scenes:
            score = sum(word in scene.content.lower() for word in words) / max(len(words), 1)
            text = scene.content[: budget.max_item_chars]
            if score < budget.min_score or total + len(text) > budget.max_total_chars:
                continue
            items.append(RecallItem(scene.scene_id, scene.version, "l2", text, float(score), scene.l1_ids))
            total += len(text)
    quotas = dict(budget.type_quotas)
    for score, row in scored:
        if sum(item.level == "l1" for item in items) >= budget.max_l1_items:
            break
        typ = row["type"]
        if typ in quotas and quotas[typ] <= 0:
            continue
        text = row["content"][: budget.max_item_chars]
        if total + len(text) > budget.max_total_chars:
            continue
        items.append(
            RecallItem(
                row["memory_id"],
                row["version"],
                "l1",
                text,
                float(score),
                tuple(
                    r[0]
                    for r in self._conn.execute(
                        "SELECT source_record_id FROM atomic_memory_sources WHERE memory_id=?", (row["memory_id"],)
                    )
                ),
            )
        )
        total += len(text)
        quotas[typ] = quotas.get(typ, 999999) - 1
    if len(items) < budget.max_l1_items and total < budget.max_total_chars and words:
        clauses = " OR ".join("LOWER(i.content) LIKE ?" for _ in words)
        l0_rows = self._conn.execute(
            f"""SELECT a.archive_id, i.source_entry_id, i.content FROM trace_items i
            JOIN trace_archives a ON a.archive_id=i.archive_id
            WHERE a.team_id=? AND a.agent_id=? AND a.user_id=? AND i.content IS NOT NULL AND ({clauses})
            ORDER BY i.store_seq DESC""",
            (*_scope(scope), *(f"%{word}%" for word in words)),
        ).fetchall()
        for row in l0_rows:
            text = str(row["content"])[: budget.max_item_chars]
            if total + len(text) > budget.max_total_chars:
                continue
            items.append(
                RecallItem(
                    f"{row['archive_id']}:{row['source_entry_id']}", 1, "l0", text, 0.3, (row["source_entry_id"],)
                )
            )
            total += len(text)
            if total >= budget.max_total_chars:
                break
    digest = content_hash("".join(f"{item.id}:{item.version}:{item.content}" for item in items))
    return RecallBundle(tuple(items), digest, total)

async def read_l2(self, scope: MemoryScope) -> tuple[WorkSceneMemory, ...]:
    """Current scenes by heat, which is the order recall reads them in."""
    rows = self._conn.execute(
        "SELECT * FROM work_scene_memories WHERE team_id=? AND agent_id=? AND user_id=? AND status='current' ORDER BY heat DESC",
        _scope(scope),
    ).fetchall()
    return tuple(self._scene(scope, row) for row in rows)

async def list_l2(
    self, scope: MemoryScope, status: str | None, after: tuple[int, str] | None, limit: int
) -> tuple[WorkSceneMemory, ...]:
    """Scene memories for the browse view, newest first.

    ``read_l2`` answers "what is current right now" for recall; browsing
    also has to reach a scene the pipeline has since marked dormant.
    """
    sql = "SELECT * FROM work_scene_memories WHERE team_id=? AND agent_id=? AND user_id=?"
    params: list[object] = list(_scope(scope))
    if status is not None:
        sql += " AND status=?"
        params.append(status)
    if after is not None:
        sql += " AND (updated_at<? OR (updated_at=? AND scene_id<?))"
        params += [after[0], after[0], after[1]]
    sql += " ORDER BY updated_at DESC, scene_id DESC LIMIT ?"
    params.append(limit)

    return len(self._sessions)

@property
def closed(self) -> bool:
    """Whether shutdown has begun; a probe reads this to drain first."""

    return self._closed

def drive_task(self, session_id: str, lane: str) -> asyncio.Task[None] | None:
    """The background drive for a lane, if one is running in this process.

    A driver running here is what distinguishes "this operation is being
    worked on" from "this operation was abandoned by a process that is gone";
    the durable record alone cannot tell them apart.
    """

    return self._drives.get((session_id, lane))

async def start(self) -> None:
    """Start the promotion workers; safe to call more than once."""

    if self._memory_runtime is not None:
        await self._memory_runtime.start()
    if self._skill_runtime is not None:
        await self._skill_runtime.start()

async def aclose(self) -> None:
    """Stop every drive, seal open sessions, then close the shared runtimes.

    ``Harness.close`` is deliberately not used: it closes the memory and
    skill runtimes, which this supervisor shares across sessions, so using
    it would leave every session after the first one without promotion.  The
    two things a session owns are its database connection and the skill
    evidence it has buffered, and both are released explicitly here.
    """

    if self._closed:
        return
    self._closed = True
    for task in list(self._drives.values()):
        task.cancel()

async def run(self) -> OperationResult:
    initial = await self._required_operation()
    await self._lane.hooks.run(
        "before_drive",
        {"lane": self._lane.name, "operation_id": initial.meta.operation_id, "kind": initial.meta.kind},
        fail_closed=True,
    )
    await self._lane.emit("operation_started", initial.meta.operation_id, {"kind": initial.meta.kind})
    self._publish(self._operation_started(initial))
    while True:
        operation = await self._required_operation()
        if operation.meta.kind == "navigation":
            return await self._run_navigation(operation)
        if operation.meta.kind == "compaction":
            return await self._run_compaction(operation)
        if operation.meta.kind != "run":
            raise RuntimeError(f"operation kind {operation.meta.kind!r} requires its structural Drive")
        if operation.state.control == "cancel_requested":
            return await self._settle_cancelled(operation)
        match operation.state.at:
            case "starting":
                await self._transition(operation, OperationState(at="checkpoint", control="running", data={}))
            case "checkpoint":
                await self._consume_inbox()
                await self._transition(operation, OperationState(at="assistant.ready", control="running", data={}))
            case "assistant.ready":
                await self._persist_generation_intent(operation)
            case "assistant.effect_pending":
                if self._provider is None:
                    raise ProviderNotConfigured("a chat provider is required to execute a generation intent")
                result = await self._execute_and_settle(operation)
                if result is not None:
                    return result
            case "assistant.retry_wait":
                await self._wait_for_retry(operation)
            case "tools":
                result = await self._run_next_tool(operation)
                if result is not None:
                    return result
            case "terminal":
                result = await self._lane.get_result(operation.meta.operation_id)
                if result is None:
                    raise RuntimeError("terminal operation has no terminal result")
                return result
            case state:
                raise RuntimeError(f"cannot drive operation from state {state!r}")

async def recover(self) -> OperationResult | None:
    operation = await self._lane.active_operation()
    if operation is None:
        return None
    if operation.state.at == "summary.effect_pending":
        return await self._settle_interrupted_compaction(operation)
    if operation.state.at != "assistant.effect_pending":
        if operation.state.at == "tools":
            data = operation.state.data

"""Read-only memory views for one repository.

Scope resolution is server-side (ADR-WEB-003): the service is built with the
deployment's repository scope, so a request can name a memory but never choose
which repository's memories are read.  L3 is the one deliberate exception —
doctrine is synthesized globally — so it is reported as global rather than
being filtered by a scope the caller could ask for.

Reads are paged by the sort key each view is ordered by.  Nothing here derives
a value the pipeline did not record: a scene with no summary stays summary-less,
and a job that never ran reports no output hash.
"""

from agent_harness.api.errors import InvalidCursor
from agent_harness.api.pagination import Page, paginate
from agent_harness.domain.memory import (
    ArchiveSummary,
    AtomicMemory,
    MemoryAuditRecord,
    MemoryScope,
    OperatingDoctrine,
    PromotionJob,
    SessionTraceArchive,
    WorkSceneMemory,
)
from agent_harness.memory.protocol import MemoryStore

_L1_STATUSES: frozenset[str] = frozenset({"active", "superseded", "rejected"})
_L2_STATUSES: frozenset[str] = frozenset({"current", "dormant"})
_JOB_STATUSES: frozenset[str] = frozenset({"scheduled", "queued", "running", "retry_wait", "dead_letter", "completed"})


class MemoryQueryService:
    """One repository's memory assets, read-only."""

    def __init__(self, store: MemoryStore, scope: MemoryScope) -> None:
        self._store = store
        self._scope = scope

    async def list_l0(self, cursor: str | None = None, limit: int = 50) -> Page[ArchiveSummary]:
        """Captured session archives, newest first."""

        async def read(after: tuple[int, str] | None, size: int) -> tuple[ArchiveSummary, ...]:
            return await self._store.list_l0(self._scope, after, size)

        return await paginate(cursor, limit, read=read, narrow=_pair("archive"), key=_archive_key)

    async def get_l0(self, archive_id: str) -> SessionTraceArchive | None:
        """One archive with its captured items, if this repository owns it."""

        archive = await self._store.read_archive(archive_id)
        return archive if archive is not None and archive.scope == self._scope else None

    async def list_l1(
        self, status: str | None = None, cursor: str | None = None, limit: int = 50
    ) -> Page[AtomicMemory]:
        """Atomic memories of every status, newest first."""

        status_filter = _status_filter(status, _L1_STATUSES, "atomic memory status")

        async def read(after: tuple[int, str] | None, size: int) -> tuple[AtomicMemory, ...]:
            return await self._store.list_l1(self._scope, status_filter, after, size)

        return await paginate(cursor, limit, read=read, narrow=_pair("memory"), key=_memory_key)

    async def list_l2(
        self, status: str | None = None, cursor: str | None = None, limit: int = 50
    ) -> Page[WorkSceneMemory]:
        """Scene memories of every status, newest first."""

        status_filter = _status_filter(status, _L2_STATUSES, "scene status")

        async def read(after: tuple[int, str] | None, size: int) -> tuple[WorkSceneMemory, ...]:
            return await self._store.list_l2(self._scope, status_filter, after, size)

        return await paginate(cursor, limit, read=read, narrow=_pair("scene"), key=_scene_key)

    async def get_l3(self) -> OperatingDoctrine | None:
        """The current operating doctrine.

        Doctrine is global: the store reads it under ``GLOBAL_L3_SCOPE`` and
        ignores this repository's scope, so callers must present it as the
        global doctrine rather than as a filtered view of this project.
        """

        return await self._store.read_l3(self._scope)

    async def list_jobs(
        self, status: str | None = None, cursor: str | None = None, limit: int = 50
    ) -> Page[PromotionJob]:
        """The promotion pipeline's jobs, newest first."""

        status_filter = _status_filter(status, _JOB_STATUSES, "job status")

